#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    int first = 1;
    for (int i = 0; i < n; i++) {
        if (i + 1 < n && a[i] == a[i + 1]) {
            if (!first) putchar(' ');
            printf("%lld", a[i]); first = 0;
            while (i + 1 < n && a[i] == a[i + 1]) i++;
        }
    }
    putchar('\n');
    return 0;
}

