int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    bool first = true;
    for (int i = 0; i < n; i++) {
        if (i + 1 < n && a[i] == a[i + 1]) {
            if (!first) cout << " ";
            cout << a[i]; first = false;
            while (i + 1 < n && a[i] == a[i + 1]) i++;
        }
    }
    cout << "\n";
    return 0;
}

