const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const counts = new Map();
    for (let i = 1; i <= n; i++) counts.set(toks[i], (counts.get(toks[i]) || 0) + 1);
    const res = [];
    for (const [k, v] of counts) if (v > 1) res.push(k);
    console.log(res.join(" "));
}
main();

